package com.johnny.hotel;import com.johnny.hotel.businessdate.BusinessDateService;import com.johnny.hotel.finance.*;import org.junit.jupiter.api.Test;import java.time.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class RevenueRecognitionServiceTest {
 @Test void recognitionUsesClosingDateAndIsRepeatSafe(){var db=mock(RevenueRecognitionMapper.class);var dates=mock(BusinessDateService.class);var d=LocalDate.of(2026,9,22);when(dates.closingPostingDate(d)).thenReturn(d);when(db.byRecognitionDate(d)).thenReturn(java.util.List.of(RevenueRecognition.builder().sourceType("FOLIO_ITEM").sourceId(1L).build()));var rows=new RevenueRecognitionService(db,dates,Clock.systemUTC()).recognize(d);assertEquals(1,rows.size());verify(db).recognizeFolioItems(eq(d),eq(d),any());}
 @Test void immutableSummaryIsCreatedOnceAndThenReturned(){var db=mock(RevenueRecognitionMapper.class);var dates=mock(BusinessDateService.class);var d=LocalDate.of(2026,9,22);var summary=DailyFinancialSummary.builder().businessDate(d).nightAuditRunId(8L).build();when(dates.closingPostingDate(d)).thenReturn(d);when(db.summary(d)).thenReturn(null,summary,summary);when(db.insertSummary(eq(d),eq(8L),any())).thenReturn(1);var service=new RevenueRecognitionService(db,dates,Clock.systemUTC());assertSame(summary,service.summarize(d,8L));assertSame(summary,service.summarize(d,8L));verify(db,times(1)).insertSummary(eq(d),eq(8L),any());}
}
